import os
import json
import base64
import requests
import subprocess

def get_azure_token():
    cmd = ["az", "account", "get-access-token", "--resource", "https://api.fabric.microsoft.com", "--query", "accessToken", "-o", "tsv"]
    res = subprocess.run(cmd, capture_output=True, text=True, check=True, shell=True)
    return res.stdout.strip()

def create_live_notebook_in_pbt(workspace_id: str, notebook_name: str, pyspark_code: str):
    token = get_azure_token()
    
    fabric_notebook_content = f"""# FABRIC CELL 1
# MARKDOWN
# # {notebook_name}
# Auto-generated by Fabric Agent for workspace PBT_DATA_AGENT

# FABRIC CELL 2
# PYSPARK
{pyspark_code}
"""
    item_metadata = {"type": "Notebook", "displayName": notebook_name}
    platform_config = {
        "$schema": "https://developer.microsoft.com/json-schemas/fabric/gitIntegration/platformProperties/2.0.0/schema.json",
        "metadata": {"type": "Notebook", "displayName": notebook_name},
        "config": {"version": "2.0", "logicalId": "00000000-0000-0000-0000-000000000000"}
    }

    b64_notebook = base64.b64encode(fabric_notebook_content.encode('utf-8')).decode('utf-8')
    b64_metadata = base64.b64encode(json.dumps(item_metadata).encode('utf-8')).decode('utf-8')
    b64_platform = base64.b64encode(json.dumps(platform_config).encode('utf-8')).decode('utf-8')

    payload = {
        "displayName": notebook_name,
        "type": "Notebook",
        "definition": {
            "parts": [
                {"path": "notebook-content.py", "payload": b64_notebook, "payloadType": "InlineBase64"},
                {"path": "item.metadata.json", "payload": b64_metadata, "payloadType": "InlineBase64"},
                {"path": ".platform", "payload": b64_platform, "payloadType": "InlineBase64"}
            ]
        }
    }

    url = f"https://api.fabric.microsoft.com/v1/workspaces/{workspace_id}/items"
    headers = {
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/json"
    }

    print(f"[LIVE DEPLOY] Posting Notebook '{notebook_name}' to Workspace ID {workspace_id}...")
    res = requests.post(url, headers=headers, json=payload)
    print(f"[API RESPONSE] Code: {res.status_code}")
    print(f"Body: {res.text}\n")
    return res

if __name__ == "__main__":
    WORKSPACE_ID = "db7344c1-ecd9-44d6-849f-f2de49484f9f"
    sample_code = """from pyspark.sql import SparkSession
from pyspark.sql.functions import col, trim, lower, current_timestamp

df = spark.read.table("lh_stage.bronze_sales")
df_clean = df.select(col("customer_id"), trim(lower(col("customer_name"))).alias("customer_name"))
display(df_clean)
"""
    create_live_notebook_in_pbt(WORKSPACE_ID, "Clean_Sales_Data_LiveTest", sample_code)
